types-of-polymorphism.html.description:
There are 2 types of polymorphism: Compile time polymorphism (Overloading/Static Dispatch)
Runtime polymorphism (Overriding/Dynamic Dispatch)
Overloading is pretty simple, but to achieve dynamic dispatch you need virtual methods and pointers.#include &lt;iostream&gt;
#include &lt;string&gt;
#include &lt;vector&gt;
#include &lt;memory&gt;
using namespace std; class Notification {
protected: string recipient; string message; public: Notification(const string&amp; recipient, const string&amp; message) : recipient(recipient), message(message) {} virtual ~Notification() {} virtual void send() { cout &lt;&lt; "Sending generic notification to " &lt;&lt; recipient &lt;&lt; endl; }
}; class EmailNotification : public Notification { string subject; public: EmailNotification(const string&amp; recipient, const string&amp; message, const string&amp; subject) : Notification(recipient, message), subject(subject) {} void send() override { cout &lt;&lt; "Sending EMAIL to " &lt;&lt; recipient &lt;&lt; " | Subject: " &lt;&lt; subject &lt;&lt; endl; }
}; class SMSNotification : public Notification { string phoneNumber; public: SMSNotification(const string&amp; recipient, const string&amp; message, const string&amp; phoneNumber) : Notification(recipient, message), phoneNumber(phoneNumber) {} void send() override { cout &lt;&lt; "Sending SMS to " &lt;&lt; phoneNumber &lt;&lt; " | Message: " &lt;&lt; message &lt;&lt; endl; }
}; class PushNotification : public Notification { string deviceToken; public: PushNotification(const string&amp; recipient, const string&amp; message, const string&amp; deviceToken) : Notification(recipient, message), deviceToken(deviceToken) {} void send() override { cout &lt;&lt; "Sending PUSH to device " &lt;&lt; deviceToken.substr(0, 8) &lt;&lt; "... | Alert: " &lt;&lt; message &lt;&lt; endl; }
}; int main() { vector&lt;unique_ptr&lt;Notification&gt;&gt; notifications; notifications.push_back(make_unique&lt;EmailNotification&gt;( "alice@example.com", "Your order shipped!", "Order Update")); notifications.push_back(make_unique&lt;SMSNotification&gt;( "Bob", "Code: 482910", "+1-555-0123")); notifications.push_back(make_unique&lt;PushNotification&gt;( "Charlie", "New message", "d8a3f4b2c1e5a9b7")); for (auto&amp; n : notifications) { n-&gt;send(); } return 0;
}

